"""Original AKC presentation. Static reading works before/without enhancement."""
import html,json
def h(x):return html.escape(str(x),quote=True)
NAV=[('article.html','先看重點'),('explore.html','動手看差別'),('method.html#originals','找原件'),('corrections.html','我有不同看法')]
def shell(title,body,pub,path,package):
 base=(pub.get('base_url') or '').rstrip('/')+'/' if pub.get('base_url') else ''
 links=''.join('<a href="'+p+'"'+(' aria-current="page"' if path==p.split('#')[0] else '')+'>'+t+'</a>' for p,t in NAV)
 current=pub['articles'][0]
 footer=''.join('<a href="'+p+'">'+t+'</a>' for p,t in [('method.html','怎麼查與原件'),('participate.html','提供來源或幫忙'),('governance.html','誰負責、誰能修改'),('funding.html','費用與資助'),('privacy.html','資料與使用方式'),('export.json','版本與資料索引'),('feed.xml','訂閱作品更新')])
 errorbase='<base href="'+h(base)+'">' if path=='404.html' else ''
 return '''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark">'''+errorbase+'''<title>'''+h(title)+'''｜AKC 公共查核</title><meta name="description" content="把查到的、查不到的說清楚。直接看重點，或打開三份圖片看看紀錄的差別。"><link rel="stylesheet" href="style.css"><link rel="canonical" href="'''+h(base+path)+'''"><link rel="alternate" type="application/rss+xml" title="訂閱AKC作品更新" href="'''+h(base+'feed.xml')+'''"></head><body><a class="skip-link" href="#main">跳到主要內容</a><header class="masthead wrap"><a class="brand" href="index.html" aria-label="AKC公共查核首頁">AKC<span>公共查核</span></a><p class="tagline">把查到的、查不到的，都說清楚。</p><nav class="main-nav" aria-label="主要入口">'''+links+'''</nav></header><main id="main" class="wrap" tabindex="-1">'''+body+'''</main><footer class="site-footer wrap"><div class="foot-grid"><div><p class="footer-heading">可以核對，也可以不同意。</p><p>AKC創辦人負責，AI（人工智慧）協助製作。現在仍由創辦人集中管理，不是獨立鑑定或分散式組織。</p><p>不參與也沒關係，直接關閉分頁就能離開。本站互動不儲存你的選擇；提供網站的GitHub仍會記錄連線資料。</p></div><nav aria-label="其他資料">'''+footer+'''</nav></div><div class="source-strip"><a href="'''+h(base+package)+'''" download>下載完整核對材料</a><a href="article.html">回到文章</a><a href="corrections.html">提出更正</a></div><p class="meta" id="edition">作品 M14-001 · 介面版 '''+h(current['version'])+''' · 原始實驗2026-10-26。版本和檔案對得上，不等於事件真實、真人已審查或保證永久可用。</p></footer></body></html>'''
def source_links():
 return '''<div class="source-strip"><a href="method.html#originals">自己看原件</a><a href="corrections.html">覺得有錯？提出更正</a><a href="article.html">直接讀完整重點</a></div>'''
def home(a,summary,stopped):
 if stopped:return '<h1>這篇目前暫停採用</h1><div class="important"><p class="article-current-summary">'+h(summary)+'</p></div>'+source_links()
 papers=''.join('<div class="paper"><span class="paper-tab">'+name+'</span><img class="paper-img" src="evidence/m14/'+file+'" alt="同一公開漸層測試圖的'+name+'"><p class="paper-caption">'+caption+'</p></div>' for name,file,caption in [('原始檔','original.jpg','讀到紀錄'),('移走紀錄','stripped-app11.jpg','找不到紀錄'),('加了註解','comment-inserted.jpg','紀錄對不上')])
 return '''<section class="hero"><div class="hero-copy"><p class="eyebrow">先別急著選相信哪一邊</p><h1>看見依據，<br>也看見還不知道。</h1><p class="lead">遇到一張圖、一句聲明或一個人工智慧答案，AKC把查到的依據、不同說法和限制放在一起，幫你保留判斷的空間。</p><div class="actions"><a class="button" href="article.html#quick-take">直接看這篇重點</a><a class="button secondary" href="explore.html">打開三份圖，看看差別</a></div><p class="utility">不用先懂技術、不用登入。互動可以跳過。</p></div><div class="hero-visual" aria-label="本篇使用的三份公開測試材料"><div class="paper-stack">'''+papers+'''</div><p class="annotation">畫面看起來一樣，檔案裡的紀錄卻不同。</p></div></section><section class="reading-steps"><div class="section-heading"><p class="eyebrow">目前從一篇作品開始</p><h2>一樣的圖片，<br>為什麼檢查答案不一樣？</h2></div><p class="article-current-summary">'''+h(summary)+'''</p><div class="three-read"><section><span class="meta">先看</span><h3>我們查到了什麼</h3><p>一份原檔、兩份明示改動的副本。這是公開測試圖，不是真人事件。</p><a href="article.html">看重點與限制</a></section><section><span class="meta">再核對</span><h3>別只相信這個網站</h3><p>原圖、工具紀錄和來源都可以自己打開、下載；查不到的也會寫出來。</p><a href="method.html#originals">開啟原件與做法</a></section><section><span class="meta">可以不同意</span><h3>覺得我們說錯了？</h3><p>指出哪句、有什麼來源。不必先完成互動，也不用付費。</p><a href="corrections.html">了解怎麼提更正</a></section></div></section><aside class="important"><h2>紀錄不是「真相保證書」。</h2><p>有紀錄，不等於事情是真的；找不到紀錄，也不能直接說是假的。人工智慧可以幫忙整理，不能替真正有權的人或平台作決定。</p></aside>'''
def article(a,summary,stopped,original):
 head='<p class="eyebrow">本篇重點 · 不必先玩互動</p><h1>'+h(a['title'])+'</h1><p class="editor-note">這裡用公開測試圖說明差別，不是在判斷真人事件。這次只改閱讀與引導，沒有重跑原始實驗；<a href="#edition">版本資料在頁尾</a>。</p>'
 if stopped:return head+'<div class="important"><p class="article-current-summary">'+h(summary)+'</p></div>'+source_links()
 return head+'''<section id="quick-take" class="quick-take"><h2>先知道這件事就好</h2><p class="article-current-summary">'''+h(summary)+'''</p><p>我們用一份官方公開的漸層測試圖，另外製作兩份副本：一份移走內嵌紀錄，一份只加檔案註解。在原來的同一解碼設定下，三份畫面的像素相同。</p><div class="result-list" aria-label="三份示範檔的結果與限制"><section class="plain-result"><h3>原始檔</h3><p class="result-label">這次讀到的紀錄</p><p>紀錄和檔案的檢查內容對得上；但這次沒有確認簽署者可信，也略過一項憑證狀態查詢。</p><p class="result-label">不能因此說</p><p>不能說事件真實、製作過程完整，或完全沒用人工智慧。</p></section><section class="plain-result"><h3>移走紀錄的副本</h3><p class="result-label">這次讀到的紀錄</p><p>這次沒有找到紀錄；這份示範是我們明示移掉的。</p><p class="result-label">不能因此說</p><p>不能把「找不到」直接當成「圖片是假」。</p></section><section class="plain-result"><h3>只加檔案註解的副本</h3><p class="result-label">這次讀到的紀錄</p><p>紀錄和檔案對不上，但畫面沒有改。程式即使傳回通常代表正常結束的0，報告仍可能寫檢查失敗。</p><p class="result-label">不能因此說</p><p>不能只憑錯誤就指控有人造假。</p></section></div></section><aside class="important"><h2>這不是對真人或事件的判決。</h2><p>我們沒有取得任何被指控者的完整原帖、回覆或事件原件。人工智慧也不能用這些結果替平台決定是否收件、採納或處罰。</p></aside><div class="actions"><a class="button secondary" href="explore.html">想慢慢看？打開三份圖</a><a href="method.html#originals">直接查原件</a></div><details class="technical"><summary>看完整查核與原始工具結果（含英文）</summary><p class="editor-note">下方沿用原查核紀錄；原始測試與規則讀取範圍是2026-10-26，並非本次重新驗證。英文狀態是工具報告，不是真假標章。</p>'''+original+'''</details><section><h2>這一版改了什麼</h2><p>'''+h(a['change_note'])+'''</p><p><a href="export.json">核對版本與前版</a> · <a href="evidence-catalog.json">核對原件與紀錄的關係</a></p></section>'''+source_links()
def explore(a,summary,stopped,data):
 intro='''<p class="eyebrow">可選的檔案探索 · 不是考試，不計分</p><h1>三張圖，<br>打開看看紀錄。</h1><p class="lead">想看哪份就點哪份。你會看到「這次查到什麼」，以及「還不能下什麼結論」。</p><p>這裡沿用原始測試的三份公開材料，沒有拿你的圖片判真假，也沒有請人工智慧現場評分。</p><div class="return-links"><a href="article.html#quick-take">不想玩，直接看重點</a><a href="method.html#originals">跳過互動，下載原件</a><a href="index.html">先離開這個體驗</a></div>'''
 if stopped:return intro+'<div class="important"><p class="article-current-summary">'+h(summary)+'</p><p>這篇目前暫停採用，互動也一併停用；沒有宣稱外部副本已撤回。</p></div>'
 cards='';panels=''
 for i,s in enumerate(data['samples']):
  cards+='<a class="sample-card" href="#record-'+h(s['key'])+'" data-sample="'+h(s['key'])+'"><span class="paper-tab">'+h(s['label'])+'</span><img src="'+h(s['path'])+'" alt="'+h(s['label'])+'：相同漸層測試圖"><span class="sample-picked" hidden>正在看這份</span></a>'
  panels+='<section class="sample-panel" id="record-'+h(s['key'])+'" aria-labelledby="heading-'+h(s['key'])+'"><h2 id="heading-'+h(s['key'])+'">'+h(s['label'])+'</h2><div class="finding"><h3>這次查到什麼</h3><p>'+h(s['finding'])+'</p></div><div class="cannot"><h3>還不能說什麼</h3><p>'+h(s['cannot'])+'</p></div><details><summary>看工具原文與對應檔案</summary><p>'+h(s['native_note'])+'</p><p><a href="'+h(s['path'])+'">打開這份原檔</a> · <a href="evidence/m14/run-summary.json">查看原測試摘要</a></p></details></section>'
 questions=''.join('<details class="question-item" data-question="'+h(q['id'])+'"><summary>'+h(q['prompt'])+'</summary><p>'+h(q['feedback'])+'</p></details>' for q in data['questions'])
 safejson=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
 return intro+'''<section class="guide-intro"><h2>先選一份，或一次看三份</h2><p id="guide-system" role="status">不用點選也能直接往下讀。若互動沒有切換，請讀下方三份說明或直接開原件。</p><div class="sample-picker" aria-label="選擇要查看的材料">'''+cards+'''</div><button class="all-toggle secondary" id="show-all" type="button" hidden>一次看三份說明</button><div class="sample-panels" id="sample-panels">'''+panels+'''</div></section><aside class="important"><h2>三份畫面相同，也不能拿來判事件真假。</h2><p>這只是同一測試圖及兩份明示控制副本，不是真人事件。紀錄有效、找不到，或對不上，都需要把來源、脈絡和有權者的規則分開看。</p></aside><section class="guide-question"><h2>你想先弄清哪件事？</h2><p>每個問題都可以自由打開，不必答完，也沒有分數。</p><div class="question-list">'''+questions+'''</div><p><a href="article.html#quick-take">回到直接閱讀</a>；即使全部看完，也不等於已替事件作真假判決。</p></section><p class="editor-note">互動只在你的瀏覽器切換文字；不儲存作答、不上傳檔案、不即時呼叫AI。玩完不表示已驗證真相或取得任何處理權。</p>'''+source_links()+'''<script type="application/json" id="guide-data">'''+safejson+'''</script><script src="guide.js" defer></script>'''
